window.products.push({"id":1150179,"name":"Joyce Chen , Saladacco Spiral Slicer, White","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/41jfVQ6FAPL._AC_.jpg","description":"Make professional garnishes in minutes with the Joyce Chen Spiral Slicer. It quickly creates spiral strands, ribbons, or slices and collects them in a clear plastic catch tray. The spiral slicer's design keeps fingers safely away from the cutting surface, providing confidence and efficiency in food preparation. Made from a durable plastic, the slicer is safe to clean in the dishwasher. It measures 9-1/2 inches tall and comes gift-boxed.","images":["https://m.media-amazon.com/images/I/41jfVQ6FAPL._AC_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"JOYCE CHEN","source_asin":"B0000DDVYE","category_path":"Home & Kitchen"},"sku":"BM-1150179","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B0000DDVYE","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B0000DDVYE","price_pending":true,"merchant_ready":false});
